// @ts-nocheck
// ── examSeniorQuestions.ts ─────────────────────────────────────
// Pilot sample (2026-09-01): situational "mise en situation / responsabilité
// de décision" questions for module d1, to test the rank-differentiated
// exam-generation pipeline before deciding whether to scale to other
// modules. See project memory (project_exams_system_architecture.md,
// "Volet 1") for the full doctrine.
//
// FINAL RULE (2026-09-01, superseding earlier drafts of this file): there is
// still only ONE mini-exam per module, scoped to the user's target rank
// (profile.target) — never multiple per-rank exams, never staged progression
// through intermediate ranks. What varies is the CONTENT MIX inside that one
// exam's question pool:
//   - a MAJORITY (70%) of situational questions at the target rank's level
//     ("master" tier below)
//   - a MINORITY (30%) of situational questions at the rank immediately
//     preceding the target ("chief_officer" tier below), to avoid too sharp
//     a difficulty jump
// Both tiers are ADDED to the general (untagged, factual) pool — never a
// replacement of it. The 70/30 weighted merge itself is NOT implemented yet
// in this pass (content-authoring only, per explicit user instruction) — see
// examEngine.ts for the current (unweighted, master-tier-only) draw logic,
// which still needs updating once this two-tier content is validated.

const LANGS = ["fr", "en", "es", "pt"];

function tagLesson(lessonId, byLang, rank, tierKey) {
  const out = {};
  for (const lang of LANGS) {
    out[lang] = (byLang[lang] || []).map((q, idx) => ({
      ...q,
      lessonId,
      questionId: `${lessonId}::${tierKey}::q${idx}`,
      relevantRanks: [rank],
    }));
  }
  return out;
}

